        simd v;
        v._r[0] = reg_t::load_aligned(p + 0);
        v._r[1] = reg_t::load_aligned(p + 1 * reg_t::lanes);
        v._r[2] = reg_t::load_aligned(p + 2 * reg_t::lanes);
        v._r[3] = reg_t::load_aligned(p + 3 * reg_t::lanes);
