        v._r[0] = reg_t::mul_add(_r[0], b._r[0], c._r[0]);
        v._r[1] = reg_t::mul_add(_r[1], b._r[1], c._r[1]);
        v._r[2] = reg_t::mul_add(_r[2], b._r[2], c._r[2]);
        v._r[3] = reg_t::mul_add(_r[3], b._r[3], c._r[3]);
        return v;
