        m._r[0] = reg_t::eq(_r[0], b._r[0]);
        m._r[1] = reg_t::eq(_r[1], b._r[1]);
        m._r[2] = reg_t::eq(_r[2], b._r[2]);
        m._r[3] = reg_t::eq(_r[3], b._r[3]);
