        auto x0 = _r[0];
        auto x1 = _r[1];
        auto x2 = _r[2];
        auto x3 = _r[3];
        x0 = reg_t::max(x0, x2);
        x1 = reg_t::max(x1, x3);
        x0 = reg_t::max(x0, x1);
