            v._r[0] = reg_t::to_f32(_r[0]);
            v._r[1] = reg_t::to_f32(_r[1]);
            v._r[2] = reg_t::to_f32(_r[2]);
            v._r[3] = reg_t::to_f32(_r[3]);
            return v;
